CREATE OR REPLACE FUNCTION public.remove_club_member(p_club_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _uid uuid;
  _my_role text;
  _target_role text;
BEGIN
  _uid := auth.uid();
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = 'P0001';
  END IF;
  IF p_user_id IS NULL OR p_user_id = _uid THEN
    RAISE EXCEPTION 'CANNOT_REMOVE_SELF' USING ERRCODE = 'P0001', HINT = 'CANNOT_REMOVE_SELF';
  END IF;
  -- same lock order as every membership change: club row first
  PERFORM 1 FROM public.clubs WHERE id = p_club_id FOR UPDATE;
  SELECT role INTO _my_role FROM public.club_members WHERE club_id = p_club_id AND user_id = _uid;
  IF _my_role IS NULL OR _my_role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'NOT_ADMIN' USING ERRCODE = 'P0001', HINT = 'NOT_ADMIN';
  END IF;
  SELECT role INTO _target_role FROM public.club_members WHERE club_id = p_club_id AND user_id = p_user_id;
  IF _target_role IS NULL THEN
    RAISE EXCEPTION 'NOT_A_MEMBER' USING ERRCODE = 'P0001';
  END IF;
  IF _target_role = 'owner' OR (_target_role = 'admin' AND _my_role <> 'owner') THEN
    RAISE EXCEPTION 'NOT_ADMIN' USING ERRCODE = 'P0001', HINT = 'NOT_ADMIN';
  END IF;
  DELETE FROM public.club_members WHERE club_id = p_club_id AND user_id = p_user_id;
  RETURN jsonb_build_object('success', true, 'removed', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.club_realtime_signal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_row record;
  v_club uuid;
  v_actor uuid := auth.uid();
  v_state text;
begin
  if tg_op = 'DELETE' then v_row := old; else v_row := new; end if;

  if tg_table_name = 'clubs' then
    v_club := v_row.id;
  elsif tg_table_name in ('club_rails', 'club_polls', 'club_members') then
    v_club := v_row.club_id;
  elsif tg_table_name = 'club_rail_items' then
    select cr.club_id into v_club from public.club_rails cr where cr.id = v_row.rail_id;
  elsif tg_table_name = 'club_votes' then
    select cp.club_id into v_club from public.club_polls cp where cp.id = v_row.poll_id;
  elsif tg_table_name = 'club_rail_item_reactions' then
    select cr.club_id into v_club
      from public.club_rail_items cri join public.club_rails cr on cr.id = cri.rail_id
     where cri.id = v_row.rail_item_id;
  end if;

  perform public._club_activity_bump(v_club);

  if tg_table_name = 'club_members' then
    -- the auth user is being deleted (FK cascade): its signal rows go with it
    if exists (select 1 from auth.users where id = v_row.user_id) then
      if tg_op = 'INSERT' then
        v_state := 'member';
      elsif tg_op = 'DELETE' then
        v_state := case
          when not exists (select 1 from public.clubs where id = old.club_id) then 'club_deleted'
          when v_actor is not null and v_actor <> old.user_id then 'removed'
          else 'left'
        end;
      end if;
      if v_state is not null then
        insert into public.club_membership_signals as s (user_id, club_id, state, revision, changed_at)
        values (v_row.user_id, v_row.club_id, v_state, 1, now())
        on conflict (user_id, club_id) do update
          set state = excluded.state, revision = s.revision + 1, changed_at = now();
      end if;
    end if;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.club_disclosure_signal_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare cid uuid; member record;
begin
 if TG_TABLE_NAME='clubs' then cid:=new.id; else cid:=coalesce(new.club_id,old.club_id); end if;
 for member in select user_id from public.club_members where club_id=cid loop
   insert into public.club_membership_signals as signal(user_id,club_id,state,revision,changed_at)
   values(member.user_id,cid,'member',1,now()) on conflict(user_id,club_id) do update set
     state='member',revision=signal.revision+1,changed_at=now();
 end loop;
 return null;
end; $function$
